package com.mygo.music;
import android.content.Context;
import java.io.*;
import java.net.*;
import java.util.*;

/** Native audio helpers use the existing Java TLS/HLS path, retaining origin-bound headers and cancellation. */
final class PluginHelperNetwork implements AutoCloseable {
 final List<String> args=new ArrayList<>();private final ArrayList<HlsAudioProxy> transports=new ArrayList<>();private volatile boolean closed;
 PluginHelperNetwork(Context context,String id,List<String> original)throws Exception{try{Map<String,String> headers=new HashMap<>();String explicitProxy="";for(int p=0;p+1<original.size();p++)if(original.get(p).equals("-http_proxy"))explicitProxy=original.get(p+1);for(int i=0;i+1<original.size();i++){String flag=original.get(i);if(flag.equals("-user_agent"))headers.put("User-Agent",original.get(i+1));if(flag.equals("-headers"))for(String line:original.get(i+1).split("\\r?\\n")){int colon=line.indexOf(':');if(colon>0){String name=line.substring(0,colon).trim(),value=line.substring(colon+1).trim();if(name.equalsIgnoreCase("Host")||name.equalsIgnoreCase("Content-Length")||name.equalsIgnoreCase("Transfer-Encoding"))continue;headers.put(name,value);}}}
  for(int i=0;i<original.size();i++){String value=original.get(i);if(value.equals("-http_proxy")||value.equals("-headers")){if(i+1>=original.size())throw new IOException("音频辅助程序缺少网络参数");i++;continue;}args.add(value);if(value.equals("-i")&&i+1<original.size()){String input=original.get(++i);if(input.startsWith("http://")||input.startsWith("https://")){if(!context.getSharedPreferences("library",0).getBoolean("plugin_network_"+id,false))throw new IOException("请先在插件网络权限中允许访问");URL origin=new URL(input);if(!explicitProxy.isEmpty()&&!systemProxyMatches(origin,explicitProxy))throw new IOException("请在 Android 系统中配置此代理，以保持账号与音频使用同一网络策略");if(input.toLowerCase(java.util.Locale.ROOT).contains(".m3u8")||input.contains("/manifest/hls")){args.remove(args.size()-1);args.addAll(Arrays.asList("-allowed_extensions","ALL","-extension_picky","0","-i"));}Map<String,String> explicit=new HashMap<>(headers);HlsAudioProxy proxy=new HlsAudioProxy(child->{if(PluginMedia.sameOrigin(origin,new URL(child)))return new HashMap<>(explicit);return Collections.emptyMap();},()->{if(closed||Thread.currentThread().isInterrupted())throw new IOException("辅助程序网络请求已取消");},Long.MAX_VALUE,true);transports.add(proxy);args.add(proxy.address(input));}else args.add(input);}}
 }catch(Exception error){close();throw error;}}
 private boolean systemProxyMatches(URL input,String selected)throws Exception{URI desired=new URI(selected);ProxySelector selector=ProxySelector.getDefault();if(selector==null)return false;for(Proxy proxy:selector.select(input.toURI())){if(proxy.type()==Proxy.Type.DIRECT)return false;if(proxy.type()==Proxy.Type.HTTP&&proxy.address() instanceof InetSocketAddress){InetSocketAddress address=(InetSocketAddress)proxy.address();return address.getPort()==desired.getPort()&&address.getHostString().equalsIgnoreCase(desired.getHost());}}return false;}
 @Override public void close(){if(closed)return;closed=true;for(HlsAudioProxy proxy:transports){Thread thread=new Thread(proxy::close,"plugin-helper-network-close");thread.setDaemon(true);thread.start();}transports.clear();}
}
